package com.dlxyuki.wms.pickingbol;
import com.dlxyuki.wms.user.UserAccount;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/bols") public class BolController{private static final MediaType XLSX=MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");private final PickingBolService service;public BolController(PickingBolService s){service=s;}@GetMapping List<Map<String,Object>> list(@AuthenticationPrincipal UserAccount u){return service.listBols(u);}@GetMapping("/{bolId}/xlsx") ResponseEntity<byte[]> export(@PathVariable long bolId,@AuthenticationPrincipal UserAccount u){var b=service.getBol(bolId,u);return ResponseEntity.ok().contentType(XLSX).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+b.get("bol_no")+".xlsx").body(service.exportBol(bolId,u));}@GetMapping("/{bolId}/pdf") ResponseEntity<byte[]> pdf(@PathVariable long bolId,@AuthenticationPrincipal UserAccount u){var b=service.getBol(bolId,u);return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+b.get("bol_no")+".pdf").body(service.exportBolPdf(bolId,u));}@GetMapping("/{bolId}") Map<String,Object> get(@PathVariable long bolId,@AuthenticationPrincipal UserAccount u){return service.getBol(bolId,u);}}
